  cbSaveOk: async t => { const [kind, sub] = t.dataset.v.split('|'), id = t.dataset.k, err = m => { const e = document.getElementById('cfErr'); if (e) { e.textContent = m; e.hidden = false; } toast(m, 'bad'); }; const tx = Store.clone(CT()), bid = v('cf_bid') || '', amt = +v('cf_amt') || 0, purpose = (v('cf_purpose') || '').trim(), f = document.getElementById('cf_file'), attach = f && f.files[0] ? f.files[0].name : (id !== 'new' ? (cbFind(tx, id) || {}).attach || '' : ''); if (!(amt > 0) || !purpose) return err('Enter the amount and purpose.'); if (bid && !cbScope().has(bid)) return err('Outside your branch scope.'); if (CM().cfg.lockedPeriods.includes((v('cf_date') || PROC_TODAY).slice(0, 7))) return err('That month is locked by Finance.'); const u = App.user; let d = id === 'new' ? null : cbFind(tx, id);
    if (kind === 'voucher') { const o = { bid, dept: v('cf_dept'), date: v('cf_date'), cat: v('cf_cat'), cc: `CC-${bid || 'CORP'}-${cbCat(v('cf_cat')).bud}`, payee: (v('cf_payee') || '').trim(), purpose, amount: amt, bill: (v('cf_bill') || '').trim(), vendor: v('cf_vendor'), tax: +v('cf_tax') || 0, attach, emergency: v('cf_em') === '1', emergencyReason: v('cf_emr'), exception: v('cf_exc'), when: v('cf_when'), remarks: v('cf_rem') }; if (!o.payee) return err('Enter the payee.'); if (o.emergency && !o.emergencyReason) return err('Enter the emergency reason.'); const st = cbDayState(bid, PROC_TODAY, tx); if (st.blocked) return err('Opening cash discrepancy not yet approved – transactions are blocked.'); if (!d) { d = Object.assign({ id: 'V' + Date.now().toString(36), no: cbNo(tx, 'PV'), kind: 'voucher', createdBy: u.id, createdByName: u.name, createdAt: nowIso(), status: 'Draft', level: 0, chain: [], log: [] }, o); tx.vouchers.unshift(d); cbLog(d, 'Created'); } else { Object.assign(d, o); if (d.status === 'Returned') d.status = 'Draft'; cbLog(d, 'Edited'); } const bad = cbChecks(d, tx).filter(a => ['Duplicate bill', 'Restricted category'].includes(a.k)); if (bad.length && sub) return err(bad.map(a => a.t).join(' · ')); }
    else if (kind === 'advance') { const emp = userById(v('cf_emp')); if (!emp) return err('Select the employee.'); if (amt > CM().cfg.advanceMax) return err(`Advance above the ${INR(CM().cfg.advanceMax)} limit.`); const over = cbOverdueAdvances(emp.id, tx).filter(x => !d || x.id !== d.id); if (over.length && !App.ui.cbAdvExc) return err(`${pName(emp)} has an overdue advance (${over.map(x => x.no).join(', ')}). Finance must grant an exception first.`); const o = { bid, emp: emp.id, empName: pName(emp), dept: v('cf_dept'), bud: v('cf_bud'), cc: `CC-${bid || 'CORP'}-${v('cf_bud')}`, purpose, amount: amt, dueDate: v('cf_due'), attach, remarks: v('cf_rem') }; if (!d) { d = Object.assign({ id: 'A' + Date.now().toString(36), no: cbNo(tx, 'AD'), kind: 'advance', createdBy: u.id, createdByName: u.name, createdAt: nowIso(), status: 'Draft', level: 0, chain: [], log: [], spent: 0 }, o); tx.advances.unshift(d); cbLog(d, 'Created'); } else { Object.assign(d, o); cbLog(d, 'Edited'); } }
    else { const emp = userById(v('cf_emp')); if (!emp) return err('Select the employee.'); if (!attach) return err('Attach the bill / receipt.'); const o = { bid, emp: emp.id, empName: pName(emp), dept: v('cf_dept'), cat: v('cf_cat'), cc: `CC-${bid || 'CORP'}-${cbCat(v('cf_cat')).bud}`, expDate: v('cf_date'), purpose, amount: amt, attach, approvalRef: v('cf_ref'), bank: v('cf_bank'), remarks: v('cf_rem') }; if (!d) { d = Object.assign({ id: 'B' + Date.now().toString(36), no: cbNo(tx, 'RB'), kind: 'reimb', createdBy: u.id, createdByName: u.name, createdAt: nowIso(), status: 'Draft', level: 0, chain: [], log: [] }, o); tx.reimb.unshift(d); cbLog(d, 'Created'); } else { Object.assign(d, o); cbLog(d, 'Edited'); } }
    if (sub) cbSubmitDoc(tx, d); await cbSave(tx); audit('Petty Cash', `${kind} ${sub ? 'submitted' : 'saved'}`, { new: `${d.no} · ${pcBr(bid)} · ${INR(amt)} · ${purpose.slice(0, 60)}`, approval: sub ? 'Pending' : 'Draft' }); App.ui.cbAdvExc = false; closeModal(); toast(`${d.no} ${sub ? 'submitted' : 'saved'}.`); },
  cbSubmit: async t => { const tx = Store.clone(CT()), d = cbFind(tx, t.dataset.k); cbSubmitDoc(tx, d); await cbSave(tx); audit('Petty Cash', d.kind + ' submitted', { new: d.no }); closeModal(); toast(d.no + ' submitted.'); },
  cbDecide: t => { const d = cbFind(CT(), t.dataset.k), a = t.dataset.v; pcRemark(`${a} · ${d.no}`, `${d.chain[d.level].label} · ${INR(d.amount)}${a === 'Approve' && d.level === d.chain.length - 1 ? ' · final approval' : ''}`, a !== 'Approve', async rem => { await cbDecide(d.id, a, rem); toast(`${d.no}: ${a.toLowerCase()}${a === 'Approve' ? 'd' : a === 'Hold' ? '' : 'ed'}.`); }); },
