  cbPay: t => pcRemark('Pay voucher in cash', 'Confirm the cash payment to the payee. Stock of cash reduces immediately and the voucher is closed.', false, async rem => { const tx = Store.clone(CT()), d = tx.vouchers.find(x => x.id === t.dataset.k); if (d.status !== 'Approved') return toast('The voucher is not approved for payment.', 'bad'); if (!cbIsCustodian(d.bid)) return toast('Only the custodian can pay.', 'bad'); if (d.createdBy === App.user.id && !CM().cfg.allowSelf && d.payee.toLowerCase().includes(App.user.name.split(' ')[0].toLowerCase())) return toast('A custodian cannot pay a voucher to themselves without authorised segregation.', 'bad'); const bal = cbBalance(d.bid, '9999-12-31', tx); if (d.amount > bal) return toast(`Insufficient petty cash (${INR(bal)}). Complete replenishment first.`, 'bad'); const st = cbDayState(d.bid, PROC_TODAY, tx); if (st.blocked) return toast('Opening discrepancy not approved – payments blocked.', 'bad'); if (!st.d) return toast('Confirm the opening cash for today before paying.', 'bad'); d.status = 'Paid'; d.paidAt = nowIso(); d.paidBy = App.user.name; cbLog(d, 'Paid in cash', rem); cbPost(tx, d.bid, -d.amount, 'Payment', d.no, { cat: d.cat }); await cbSave(tx); audit('Petty Cash', 'Voucher paid', { new: `${d.no} · ${d.payee} · ${INR(d.amount)}`, reason: rem }); cbDoc(d.id); }),
