  cbDisburse: t => pcRemark('Disburse cash advance', 'Confirm cash handed to the employee.', false, async rem => { const tx = Store.clone(CT()), d = tx.advances.find(x => x.id === t.dataset.k); if (d.status !== 'Approved' || !cbIsCustodian(d.bid)) return toast('Only the custodian can disburse an approved advance.', 'bad'); const bal = cbBalance(d.bid, '9999-12-31', tx); if (d.amount > bal) return toast(`Insufficient petty cash (${INR(bal)}).`, 'bad'); d.status = 'Disbursed'; d.disbursedAt = nowIso(); cbLog(d, 'Advance disbursed', rem); cbPost(tx, d.bid, -d.amount, 'Advance', d.no); cbNotify([d.emp], `${d.no}: advance of ${INR(d.amount)} disbursed – settle with bills by ${isoLabel(d.dueDate)}`, d.id, 'cb_advances'); await cbSave(tx); audit('Petty Cash', 'Advance disbursed', { new: `${d.no} · ${d.empName} · ${INR(d.amount)}` }); cbDoc(d.id); }),
  cbSettleForm: t => { const d = CT().advances.find(x => x.id === t.dataset.k); modal(`Settle advance · ${d.no}`, `<p class="small">${esc(d.empName)} · advance ${INR(d.amount)} · due ${isoLabel(d.dueDate)}</p><div class="form-grid">${pcFld('Amount spent (₹, per bills)', `<input id="se_spent" type="number" min="0" value="${d.amount}">`)}${pcFld('Bills / receipts', '<input id="se_file" type="file" multiple>')}</div><label class="fld"><span>Settlement details</span><textarea id="se_note" rows="2"></textarea></label><p class="small muted">Excess advance is refunded to petty cash; expenditure above the advance is reimbursed to the employee.</p>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="cbSettleOk" data-k="${d.id}">Submit settlement</button>`); },
  cbSettleOk: async t => { const tx = Store.clone(CT()), d = tx.advances.find(x => x.id === t.dataset.k), spent = +v('se_spent') || 0, f = document.getElementById('se_file'); if (!f.files.length && spent > 0) return toast('Attach the bills.', 'bad'); d.spent = spent; d.settledAt = nowIso(); d.bills = [...f.files].map(x => x.name).join(', '); d.status = 'Settled'; cbLog(d, 'Settlement submitted', `${v('se_note')} · spent ${INR(spent)}`); const diff = d.amount - spent; if (diff > 0) cbPost(tx, d.bid, diff, 'Advance refund', d.no); else if (diff < 0) cbPost(tx, d.bid, diff, 'Payment', d.no + ' (excess reimbursed)', { cat: 'OTP' }); await cbSave(tx); audit('Petty Cash', 'Advance settled', { old: d.no, new: `spent ${INR(spent)} · ${diff >= 0 ? 'refund ' + INR(diff) : 'reimbursed ' + INR(-diff)}` }); closeModal(); toast(d.no + ' settled.'); },
  cbAdvException: () => { App.ui.cbAdvExc = true; toast('Exception noted – resubmit the advance.'); },
