  cbReplenOk: async t => { const tx = Store.clone(CT()), bid = t.dataset.k, amt = +v('rp_amt') || 0; if (!(amt > 0)) return toast('Enter the amount.', 'bad'); const s = cbSetup(bid), bal = cbBalance(bid, '9999-12-31', tx), from = t.dataset.f; const V = tx.vouchers.filter(x => x.bid === bid && x.status === 'Paid' && x.paidAt.slice(0, 10) > from), A = tx.ledger.filter(e => e.bid === bid && e.date > from); const d = { id: 'R' + Date.now().toString(36), no: cbNo(tx, 'RP'), kind: 'replen', bid, from, to: PROC_TODAY, open: cbBalance(bid, from, tx), expenses: V.reduce((a, x) => a + x.amount, 0), advances: -A.filter(e => e.type === 'Advance').reduce((a, e) => a + e.amount, 0), returned: A.filter(e => /Return|Refund/.test(e.type)).reduce((a, e) => a + e.amount, 0), closing: bal, amount: amt, source: v('rp_src'), remarks: v('rp_rem'), createdBy: App.user.id, createdByName: App.user.name, createdAt: nowIso(), status: 'Draft', level: 0, chain: [], log: [] }; tx.replen.unshift(d); cbLog(d, 'Created'); cbSubmitDoc(tx, d); await cbSave(tx); audit('Petty Cash', 'Replenishment requested', { new: `${d.no} · ${pcBr(bid)} · ${INR(amt)}`, approval: 'Pending' }); closeModal(); toast(d.no + ' submitted.'); },
  cbReplenRecv: t => pcRemark('Record cash received', 'Bank withdrawal / transfer / handover reference. The custodian acknowledges receipt and the balance increases.', true, async rem => { const tx = Store.clone(CT()), d = tx.replen.find(x => x.id === t.dataset.k); if (d.status !== 'Approved') return toast('Not approved yet.', 'bad'); d.status = 'Received'; d.receivedAt = nowIso(); d.voucherNo = cbNo(tx, 'RV'); d.ack = { by: App.user.name, at: nowIso(), ref: rem }; cbLog(d, 'Cash received and acknowledged', rem); cbPost(tx, d.bid, d.amount, 'Replenishment', d.voucherNo, { note: d.source + ' · ' + rem }); await cbSave(tx); audit('Petty Cash', 'Replenishment received', { new: `${d.no} · ${d.voucherNo} · ${INR(d.amount)} · ${d.source}`, reason: rem }); cbDoc(d.id); }),
  cbOpenOk: async t => { const tx = Store.clone(CT()), bid = t.dataset.k, st = cbDayState(bid, PROC_TODAY, tx), phys = +v('op_phys') || 0, reason = (v('op_reason') || '').trim(), diff = phys - st.open; if (diff && !reason) return toast('Enter the reason for the difference.', 'bad'); if (cbDay(bid, PROC_TODAY, tx)) return toast('Opening already confirmed.', 'bad'); const f = document.getElementById('op_file'); const d = { id: 'D' + bid + PROC_TODAY, bid, date: PROC_TODAY, openSys: st.open, openPhys: phys, openDiff: diff, openReason: reason, openAt: nowIso(), openBy: App.user.name, attach: f && f.files[0] ? f.files[0].name : '' }; tx.days.push(d); if (diff && Math.abs(diff) > CM().cfg.tolerance) { cbPost(tx, bid, diff, 'Cash discrepancy', 'Opening ' + PROC_TODAY, { note: reason }); cbNotify([...(pcPrincipal(bid) ? [pcPrincipal(bid)] : []), ...PROC_FIN_ROLES.flatMap(r => pcUsersByRole(r)), ...pcUsersByRole('Auditor')], `${pcBr(bid)}: opening cash discrepancy ${INR(diff)} on ${isoLabel(PROC_TODAY)} – ${reason}`, d.id, 'cb_day'); } await cbSave(tx); audit('Petty Cash', 'Opening cash confirmed', { new: `${pcBr(bid)} · system ${INR(st.open)} · counted ${INR(phys)}`, reason, approval: diff ? 'Discrepancy – pending approval' : '—' }); closeModal(); toast('Opening cash confirmed.'); },
  cbCloseOk: async t => { const tx = Store.clone(CT()), bid = t.dataset.k, date = t.dataset.d, st = cbDayState(bid, date, tx), phys = +v('cl_phys') || 0, reason = (v('cl_reason') || '').trim(), diff = phys - st.expected; if (diff && !reason) return toast('Enter the reason for the difference.', 'bad'); const d = tx.days.find(x => x.bid === bid && x.date === date); if (!d) return toast('Confirm the opening first.', 'bad'); const f = document.getElementById('cl_file'); Object.assign(d, { expected: st.expected, closePhys: phys, closeDiff: diff, reason, closedAt: nowIso(), closedBy: App.user.name, attach: [...(f.files || [])].map(x => x.name).join(', ') || d.attach }); if (diff && Math.abs(diff) > CM().cfg.tolerance) { cbPost(tx, bid, diff, 'Cash discrepancy', 'Closing ' + date, { note: reason, date }); cbNotify([...(pcPrincipal(bid) ? [pcPrincipal(bid)] : []), ...PROC_FIN_ROLES.flatMap(r => pcUsersByRole(r)), ...pcUsersByRole('Auditor')], `${pcBr(bid)}: closing cash difference ${INR(diff)} on ${isoLabel(date)} – ${reason}`, d.id, 'cb_day'); } const s = cbSetup(bid); if (s.verifier) cbNotify([s.verifier.id], `${pcBr(bid)}: daily cash closing for ${isoLabel(date)} awaits your verification (closing ${INR(phys)})`, d.id, 'cb_day'); const bal = cbBalance(bid, '9999-12-31', tx); if (bal < s.floatAmt * CM().cfg.replenishPct / 100 && !tx.replen.some(r => r.bid === bid && ['Submitted', 'Approved'].includes(r.status))) cbNotify(s.custodian ? [s.custodian.id] : [], `${pcBr(bid)}: cash ${INR(bal)} is below the replenishment threshold – raise a replenishment request`, bid, 'cb_replenish'); await cbSave(tx); audit('Petty Cash', 'Daily cash closed', { new: `${pcBr(bid)} · ${date} · expected ${INR(st.expected)} · counted ${INR(phys)}`, reason, approval: diff ? 'Discrepancy' : 'Balanced' }); closeModal(); toast('Day closed – awaiting verifier confirmation.'); },
  cbVerifyClose: t => pcRemark('Verify daily closing', 'Confirm you have verified the closing cash and supporting documents.', false, async rem => { const tx = Store.clone(CT()), d = tx.days.find(x => x.id === t.dataset.k); if (d.closedBy === App.user.name && App.user.role !== 'Super Admin') return toast('The custodian cannot verify their own closing.', 'bad'); d.verifiedAt = nowIso(); d.verifiedBy = App.user.name; d.verifyNote = rem; await cbSave(tx); audit('Petty Cash', 'Daily closing verified', { new: `${pcBr(d.bid)} · ${d.date} · ${INR(d.closePhys)}`, reason: rem, approver: App.user.name }); }),
  cbDiscOk: t => pcRemark('Approve cash discrepancy', 'The explanation is accepted; transactions resume. Recovery or write-off is recorded in Finance.', true, async rem => { const tx = Store.clone(CT()), d = tx.days.find(x => x.id === t.dataset.k); d.openApproved = App.user.name; d.discApproved = App.user.name; d.discNote = rem; await cbSave(tx); audit('Petty Cash', 'Cash discrepancy approved', { new: `${pcBr(d.bid)} · ${d.date} · ${INR(d.openDiff || d.closeDiff)}`, reason: rem, approver: App.user.name }); }),
