  cbVerifOk: async t => { const tx = Store.clone(CT()), bid = t.dataset.k, bal = cbBalance(bid, '9999-12-31', tx), phys = +v('vf_phys') || 0, diff = phys - bal, exp = (v('vf_exp') || '').trim(); if (diff && !exp) return toast('Explain the difference.', 'bad'); const f = document.getElementById('vf_file'); const x = { id: 'VF' + Date.now().toString(36), no: cbNo(tx, 'VF'), bid, at: nowIso(), kind: v('vf_kind'), system: bal, physical: phys, diff, explanation: exp, verifier: App.user.name, custodian: v('vf_cust'), attach: f && f.files[0] ? f.files[0].name : '', action: v('vf_action'), status: diff ? 'Open' : 'Closed' }; tx.verifs.unshift(x); if (diff && Math.abs(diff) > CM().cfg.tolerance) { cbPost(tx, bid, diff, 'Cash discrepancy', x.no, { note: exp }); cbNotify([...PROC_FIN_ROLES.flatMap(r => pcUsersByRole(r)), ...pcUsersByRole('Auditor')], `${pcBr(bid)}: verification ${x.no} found difference ${INR(diff)} – ${exp}`, x.id, 'cb_day'); } await cbSave(tx); audit('Petty Cash', 'Cash verification recorded', { new: `${x.no} · ${pcBr(bid)} · system ${INR(bal)} · counted ${INR(phys)}`, reason: exp, approval: diff ? x.action : 'Balanced' }); closeModal(); toast(x.no + ' recorded.'); },
  cbHandForm: t => { const bid = t.dataset.k; modal(`Cash handover / deposit · ${pcBr(bid)}`, `<div class="form-grid">${pcFld('Amount (₹)', `<input id="ho_amt" type="number" min="1">`)}${pcFld('Receiver', '<input id="ho_recv" value="Corporate Finance – cashier">')}${pcFld('Cash receipt no.', '<input id="ho_rcpt">')}${pcFld('Deposit proof', '<input id="ho_file" type="file">')}</div><label class="fld"><span>Remarks</span><input id="ho_rem"></label>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="cbHandOk" data-k="${bid}">Record handover</button>`); },
  cbHandOk: async t => { const tx = Store.clone(CT()), bid = t.dataset.k, amt = +v('ho_amt') || 0; if (!(amt > 0)) return toast('Enter the amount.', 'bad'); if (amt > cbBalance(bid, '9999-12-31', tx)) return toast('Amount exceeds cash in hand.', 'bad'); const f = document.getElementById('ho_file'); const h = { id: 'HO' + Date.now().toString(36), no: cbNo(tx, 'HO'), bid, at: nowIso(), amount: amt, sender: App.user.name, receiver: v('ho_recv'), receipt: v('ho_rcpt'), ack: null, proof: f && f.files[0] ? f.files[0].name : '', remarks: v('ho_rem') }; tx.handovers.unshift(h); cbPost(tx, bid, -amt, 'Handover', h.no); cbNotify(PROC_FIN_ROLES.flatMap(r => pcUsersByRole(r)), `${h.no}: ${INR(amt)} handed over from ${pcBr(bid)} – acknowledge receipt`, h.id, 'cb_day'); await cbSave(tx); audit('Petty Cash', 'Cash handover recorded', { new: `${h.no} · ${pcBr(bid)} · ${INR(amt)} · ${h.receiver}` }); closeModal(); toast(h.no + ' recorded.'); },
