PAGES.cb_reports = { title: 'Petty Cash Reports', mod: 'cb_reports', group: true, render() {
  const key = CB_REPORTS.some(r => r[0] === App.ui.cbRep) ? App.ui.cbRep : 'book', def = CB_REPORTS.find(r => r[0] === key); let R; try { R = def[2](); } catch (e) { console.error(e); return `<div class="note bad">${esc(e.message)}</div>`; }
  const f = App.ui.cbRF || {}; let rows = R.rows; if (f.cat) rows = rows.filter(r => !r.cat || r.cat === f.cat || cbCat(f.cat).name === r.cat); if (f.st) rows = rows.filter(r => !r.status || r.status === f.st); if (f.from || f.to) rows = rows.filter(r => { const d = r.date || (r.at || r.createdAt || r.ts || r.disbursedAt || '').slice(0, 10) || (r.ym ? r.ym + '-01' : ''); return !d || ((!f.from || d >= f.from) && (!f.to || d <= f.to)); });
  const NOSUM = /days|vouchers|accounts|utilisation|limit/i, totalVals = rows.length ? R.cols.map(c => ['inr', 'num'].includes(c.t) && !NOSUM.test(c.h) ? rows.reduce((s, r) => { let x; try { x = c.x ? c.x(r) : c.k(r); } catch (e) { x = 0; } return s + (typeof x === 'number' && isFinite(x) ? x : 0); }, 0) : null) : null;
  return `<div class="srf-strip2"><label class="fld"><span>Report</span><select data-act="uiSel" data-k="cbRep">${CB_REPORTS.map(([k, l]) => `<option value="${k}" ${k === key ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></label><label class="fld"><span>Category</span><select data-act="cbRF" data-k="cat"><option value="">All</option>${CM().cats.map(c => `<option value="${c.id}" ${f.cat === c.id ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select></label><label class="fld"><span>Status</span><select data-act="cbRF" data-k="st"><option value="">All</option>${['Submitted', 'Approved', 'Paid', 'Disbursed', 'Settled', 'Received', 'Rejected', 'Cancelled', 'Reversed'].map(s => `<option ${f.st === s ? 'selected' : ''}>${s}</option>`).join('')}</select></label><label class="fld"><span>From</span><input type="date" data-act="cbRF" data-k="from" value="${f.from || ''}"></label><label class="fld"><span>To</span><input type="date" data-act="cbRF" data-k="to" value="${f.to || ''}"></label><span class="grow"></span><span class="small">${rows.length} rows · business type, region, zone and branch from the filter bar</span></div>${card(def[1], table('cbRep', R.cols, rows, { totalVals, compact: true, title: def[1], limit: 150, empty: 'No records for this report and the selected filters.' }), { right: exportBtns('cbRep', 'cb_reports') })}`;
} };
