  let body;
  if (tab === 'policy') body = `<h4 class="blk">Float by business type</h4><div class="form-grid">${Object.keys(c.floatByType).map(t => pcFld(t, num('f_' + t.replace(/\W/g, '_'), c.floatByType[t]))).join('')}</div><h4 class="blk">Limits</h4><div class="form-grid">${pcFld('Maximum single transaction (₹)', num('p_single', c.singleMax))}${pcFld('Branch transaction cap (₹)', num('p_cap', c.branchCap))}${pcFld('Daily transaction limit (₹)', num('p_daily', c.dailyMax))}${pcFld('Monthly limit (% of float)', num('p_monthly', c.monthlyPct))}${pcFld('Replenishment threshold (% of float)', num('p_repl', c.replenishPct))}${pcFld('Cash discrepancy tolerance (₹)', num('p_tol', c.tolerance))}${pcFld('Block transactions on unexplained discrepancy', pcSel('p_block', [['1', 'Yes'], ['0', 'No – warn only']], c.blockOnDiscrepancy ? '1' : '0'))}${pcFld('Daily closing deadline', `<input id="p_dead" type="time" value="${c.closingDeadline}" ${ed ? '' : 'disabled'}>`)}${pcFld('Advance settlement (days)', num('p_advd', c.advanceDays))}${pcFld('Maximum advance (₹)', num('p_advm', c.advanceMax))}${pcFld('Bill mandatory', pcSel('p_bill', [['1', 'Yes (exception with justification)'], ['0', 'No']], c.billRequired ? '1' : '0'))}${pcFld('Split detection: vouchers to same payee within (days)', num('p_splitd', c.splitWindowDays))}${pcFld('Split detection: minimum count', num('p_splitn', c.splitCount))}${pcFld('Verification schedule', pcSel('p_ver', ['Daily', 'Weekly', 'Fortnightly', 'Monthly'], c.verifyEvery))}</div>${ed ? '<button class="btn primary" data-act="cbCfgSave" data-k="policy">Save policy</button>' : ''}`;
  else if (tab === 'branches') { const rows = [''].concat(cbBranchesWithCash().map(b => b.id)).filter(bid => bid === '' ? CB_CORP() : cbScope().has(bid)).map(bid => Object.assign({ bid }, cbSetup(bid), { bal: cbBalance(bid) })); body = table('cbBrSet', [{ h: 'Branch', k: r => pcBr(r.bid), t: 'text' }, { h: 'Type', k: r => cbBtype(r.bid), t: 'text' }, { h: 'Custodian', k: r => r.custodian ? pName(r.custodian) : pill('Not mapped', 'bad'), t: 'html', x: r => r.custodian ? pName(r.custodian) : '' }, { h: 'Backup', k: r => r.backup ? pName(r.backup) : '—', t: 'text', cls: 'small' }, { h: 'Verifier', k: r => r.verifier ? pName(r.verifier) : '—', t: 'text', cls: 'small' }, { h: 'Float', k: r => r.floatAmt, t: 'inr' }, { h: 'Single max', k: r => r.singleMax, t: 'inr' }, { h: 'Daily max', k: r => r.dailyMax, t: 'inr' }, { h: 'Monthly max', k: r => r.monthlyMax, t: 'inr' }, { h: 'Cash in hand', k: r => r.bal, t: 'inr' }, { h: 'Bank', k: r => r.bank, t: 'text', cls: 'small' }, { h: '', k: r => ed ? `<button class="btn sm" data-act="cbBrForm" data-k="${r.bid}">Edit</button>` : '', t: 'html', noexp: true }], rows, { compact: true, title: 'Branch petty-cash setup', limit: 100 }); }
  else if (tab === 'cats') body = `<div class="btnrow">${ed ? '<button class="btn sm primary" data-act="cbCatForm" data-k="new">Add category</button>' : ''}</div>` + table('cbCats', [{ h: 'Code', k: x => x.id, t: 'text' }, { h: 'Category', k: x => x.name, t: 'text' }, { h: 'Budget head', k: x => pcCat(x.bud), t: 'text' }, { h: 'Per-transaction limit', k: x => x.limit, t: 'inr' }, { h: 'Status', k: x => cbStatusPill(x.active ? 'Active' : 'Inactive'), t: 'html', x: x => x.active ? 'Active' : 'Inactive' }, { h: '', k: x => ed ? `<div class="btnstack"><button class="btn sm" data-act="cbCatForm" data-k="${x.id}">Edit</button><button class="btn sm ghost" data-act="cbCatTog" data-k="${x.id}">${x.active ? 'Deactivate' : 'Activate'}</button></div>` : '', t: 'html', noexp: true }], M.cats, { compact: true, title: 'Allowed petty-cash categories' }) + card('Restricted – never through petty cash', `<p class="small">${M.restricted.map(esc).join(' · ')}</p>${ed ? '<div class="btnrow"><input id="rs_new" placeholder="Add restricted item"><button class="btn sm" data-act="cbRestrAdd">Add</button></div>' : ''}`);
  else body = `<div class="form-grid">${pcFld('Zonal Director above (₹) or any exception', num('w_zd', c.zdAbove))}${pcFld('CFO above (₹) or over budget', num('w_cfo', c.cfoAbove))}${pcFld('Replenishment: CFO above (₹)', num('w_rcfo', c.replenCfoAbove))}${pcFld('Finance approval on every voucher', pcSel('w_fin', [['1', 'Yes'], ['0', 'Only exceptions / above limits']], c.financeAlways ? '1' : '0'))}${pcFld('Requester may approve own request', pcSel('w_self', [['0', 'No'], ['1', 'Yes']], c.allowSelf ? '1' : '0'))}${pcFld('System Admin may act on any level', pcSel('w_adm', [['1', 'Yes'], ['0', 'No']], c.adminOverride ? '1' : '0'))}${pcFld('Email notifications', pcSel('w_mail', [['1', 'On (simulated)'], ['0', 'In-app only']], c.notifyEmail ? '1' : '0'))}</div><h4 class="blk">Voucher number series</h4><div class="form-grid">${Object.entries(c.numbering).map(([k, p]) => pcFld({ PV: 'Payment voucher', RV: 'Receipt / replenishment voucher', AD: 'Cash advance', RB: 'Reimbursement', RP: 'Replenishment request', VF: 'Verification', HO: 'Handover' }[k] || k, `<input id="n_${k}" value="${esc(p)}" maxlength="6" ${ed ? '' : 'disabled'}>`)).join('')}</div>${ed ? '<button class="btn primary" data-act="cbCfgSave" data-k="wf">Save workflows</button>' : ''}<h4 class="blk" style="margin-top:14px">Monthly periods</h4><p class="small">Locked: ${c.lockedPeriods.length ? c.lockedPeriods.join(', ') : 'none'}. Locked months accept no new or edited vouchers.</p>${ed && pcFinRole() || App.user.role === 'Super Admin' ? `<div class="btnrow"><input id="lk_ym" type="month" value="${pcAddDays(PROC_TODAY, -30).slice(0, 7)}"><button class="btn sm" data-act="cbLock" data-v="1">Lock month</button><button class="btn sm ghost" data-act="cbLock" data-v="0">Unlock month</button></div>` : ''}<p class="small muted">Routes: Requester → Principal → Finance → custodian payment; exceptions add Zonal Director and CFO. Advances: Employee → Principal → Finance → custodian. Replenishment: custodian → Principal → Finance → CFO above limit. Delegated approvers from Store & purchase settings apply.</p>`;
